  describe("POST /api/auth/password/forgot", () => {
    it("should request password reset successfully", async () => {
      (userManagerService.requestPasswordReset as jest.Mock).mockResolvedValue({
        success: true,
        message: "Email de réinitialisation envoyé",
      });

      const response = await request(app)
        .post("/api/auth/password/forgot")
        .send({
          email: "user@example.com",
        })
        .expect(200);

      expect(response.body).toEqual({
        success: true,
        message: "Email de réinitialisation envoyé",
      });

      expect(userManagerService.requestPasswordReset).toHaveBeenCalledWith(
        "user@example.com",
        expect.any(Number),
      );
    });

    it("should return 400 when email is missing", async () => {
      const response = await request(app)
        .post("/api/auth/password/forgot")
        .send({})
        .expect(400);

      expect(response.body).toEqual({
        success: false,
        message: "Email requis",
      });

      expect(userManagerService.requestPasswordReset).not.toHaveBeenCalled();
    });

    it("should always return success to prevent email enumeration", async () => {
      (userManagerService.requestPasswordReset as jest.Mock).mockResolvedValue({
        success: false,
        message: "Email non trouvé",
      });

      const response = await request(app)
        .post("/api/auth/password/forgot")
        .send({
          email: "nonexistent@example.com",
        })
        .expect(200);

      expect(response.body.success).toBe(true);
    });

    it("should handle service errors gracefully", async () => {
      (userManagerService.requestPasswordReset as jest.Mock).mockRejectedValue(
        new Error("Email service error"),
      );

      const response = await request(app)
        .post("/api/auth/password/forgot")
        .send({
          email: "user@example.com",
        })
        .expect(500);

      expect(response.body).toEqual({
        success: false,
        message: "Erreur lors de la demande de réinitialisation",
      });
    });
  });

